BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Right & Left Heart Failure' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Right & Left Heart Failure', 'Right-sided and left-sided heart failure', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Right & Left Heart Failure (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Right-Left Heart Failure - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "HF Definition" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "HF Definition" is most accurate?', '[{"id": "a", "text": "Heart failure always presents without fluid overload."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "d", "text": "Recognize that congestion and low forward output can coexist."}]'::jsonb, '["d"]'::jsonb, 'Correct because Heart failure is the inability of the heart to pump sufficient blood to meet metabolic needs. Recognize that congestion and low forward output can coexist.', 'Right-Left Heart Failure - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "HFrEF" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "HFrEF" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Reduced contractility contributes to poor forward output in HFrEF."}, {"id": "b", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "c", "text": "Pink frothy sputum is listed as a benign right-sided finding."}, {"id": "d", "text": "HFrEF is primarily a stiff non-compliant ventricle with preserved EF."}]'::jsonb, '["a"]'::jsonb, 'Correct because HFrEF has EF <40% with a dilated, weak heart. Link reduced EF with weakened pump function.', 'Right-Left Heart Failure - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "HFpEF" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "HFpEF" in Right & Left Heart Failure?', '[{"id": "a", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "b", "text": "HFpEF has EF >50% with a stiff, non-compliant heart."}, {"id": "c", "text": "HFpEF is a dilated weak ventricle by definition."}, {"id": "d", "text": "No further assessment is needed when symptoms fluctuate."}]'::jsonb, '["b"]'::jsonb, 'Correct because HFpEF has EF >50% with a stiff, non-compliant heart. Avoid ruling out HF just because EF is preserved.', 'Right-Left Heart Failure - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "EF Range" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "EF Range" in Right & Left Heart Failure?', '[{"id": "a", "text": "A patient can have HF symptoms even when EF is preserved."}, {"id": "b", "text": "Left HF pathophysiology excludes alveolar fluid leakage."}, {"id": "c", "text": "EF alone is always enough to diagnose or exclude HF."}, {"id": "d", "text": "This finding excludes heart failure when EF is preserved."}]'::jsonb, '["a"]'::jsonb, 'Correct because Normal EF is 55-70%; HF diagnosis can still be made if symptoms are present regardless of EF. Prioritize clinical symptoms over EF alone.', 'Right-Left Heart Failure - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Left HF Core" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Left HF Core" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "Dyspnea and crackles are hallmark left-sided findings."}, {"id": "b", "text": "Left-sided HF typically has no respiratory symptoms."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "Right-sided HF is unrelated to chronic lung disease."}]'::jsonb, '["a"]'::jsonb, 'Correct because Left-sided HF primarily causes pulmonary congestion. Map left side findings to lung congestion.', 'Right-Left Heart Failure - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "Left HF Causes" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "Left HF Causes" is most accurate?', '[{"id": "a", "text": "RV failure lowers venous pressure and prevents edema."}, {"id": "b", "text": "Orthopnea is identified as a right-sided-only symptom."}, {"id": "c", "text": "Connect structural and ischemic causes to LV failure."}, {"id": "d", "text": "Left HF is unrelated to cardiomyopathy."}]'::jsonb, '["c"]'::jsonb, 'Correct because Left HF causes include mitral/aortic valve disease, MI, chronic hypertension, cardiomyopathy. Connect structural and ischemic causes to LV failure.', 'Right-Left Heart Failure - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Left HF Path" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "Left HF Path" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Identify sequence leading to respiratory compromise."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "Left HF pathophysiology excludes alveolar fluid leakage."}]'::jsonb, '["a"]'::jsonb, 'Correct because LV failure backs blood into pulmonary veins; pressure rises and fluid leaks into alveoli causing pulmonary edema. Identify sequence leading to respiratory compromise.', 'Right-Left Heart Failure - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "DOE" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "DOE" in Right & Left Heart Failure?', '[{"id": "a", "text": "Unilateral trauma edema is listed as classic HF edema."}, {"id": "b", "text": "Dyspnea on exertion is an early left HF symptom."}, {"id": "c", "text": "DOE appears only in right-sided HF section."}, {"id": "d", "text": "No further assessment is needed when symptoms fluctuate."}]'::jsonb, '["b"]'::jsonb, 'Correct because Dyspnea on exertion is the first symptom listed for left HF. Escalate evaluation when exertional dyspnea appears in risk patients.', 'Right-Left Heart Failure - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Orthopnea and PND" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "Orthopnea and PND" in Right & Left Heart Failure?', '[{"id": "a", "text": "Orthopnea is identified as a right-sided-only symptom."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "Use nocturnal and positional dyspnea to triage severity."}, {"id": "d", "text": "No further assessment is needed when symptoms fluctuate."}]'::jsonb, '["c"]'::jsonb, 'Correct because Orthopnea and PND are classic left-sided HF symptoms. Use nocturnal and positional dyspnea to triage severity.', 'Right-Left Heart Failure - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Pulmonary edema" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Pulmonary edema" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "b", "text": "Pulmonary edema is strongly linked to left-sided failure."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "Pink frothy sputum is listed as a benign right-sided finding."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pink frothy sputum is a severe pulmonary edema sign in left HF. Treat as high-acuity respiratory compromise.', 'Right-Left Heart Failure - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "S3" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "S3" is most accurate?', '[{"id": "a", "text": "RV failure directly causes only alveolar edema."}, {"id": "b", "text": "Interpret S3 with full volume-overload context."}, {"id": "c", "text": "S3 is only a normal physiologic finding."}, {"id": "d", "text": "RV failure lowers venous pressure and prevents edema."}]'::jsonb, '["b"]'::jsonb, 'Correct because S3 gallop is described as a hallmark of heart failure (especially in left HF section). Interpret S3 with full volume-overload context.', 'Right-Left Heart Failure - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Right HF Core" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "Right HF Core" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Distinguish body-fluid retention pattern from pulmonary pattern."}, {"id": "b", "text": "BNP elevation is impossible in right HF according to this note."}, {"id": "c", "text": "JVD is listed as a hallmark of isolated left alveolar pathology."}, {"id": "d", "text": "Right-sided HF is described as isolated alveolar edema only."}]'::jsonb, '["a"]'::jsonb, 'Correct because Right-sided HF primarily causes systemic (peripheral) congestion. Distinguish body-fluid retention pattern from pulmonary pattern.', 'Right-Left Heart Failure - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Right HF Causes" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "Right HF Causes" in Right & Left Heart Failure?', '[{"id": "a", "text": "Aortic stenosis is listed as the dominant right-sided cause."}, {"id": "b", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "c", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "d", "text": "Left-sided HF is the most common cause of right-sided HF."}]'::jsonb, '["d"]'::jsonb, 'Correct because Most common right HF cause is left-sided HF; others include tricuspid disease, pulmonary HTN, RV MI, chronic lung disease. Search upstream causes when right-sided findings appear.', 'Right-Left Heart Failure - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Right HF Path" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "Right HF Path" in Right & Left Heart Failure?', '[{"id": "a", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "b", "text": "RV failure causes blood to back up in venous circulation."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "RV failure lowers venous pressure and prevents edema."}]'::jsonb, '["b"]'::jsonb, 'Correct because RV failure causes venous backup and systemic fluid accumulation. Connect venous pressure rise to peripheral signs.', 'Right-Left Heart Failure - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "JVD" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "JVD" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "BiPAP is contraindicated in refractory pulmonary edema per this note."}, {"id": "b", "text": "Ascites is listed as a defining left-sided pulmonary finding."}, {"id": "c", "text": "JVD reflects elevated venous pressure and is a major right HF sign."}, {"id": "d", "text": "JVD is listed as a hallmark of isolated left alveolar pathology."}]'::jsonb, '["c"]'::jsonb, 'Correct because JVD reflects elevated venous pressure and is a major right HF sign. Use JVD as high-yield bedside congestion marker.', 'Right-Left Heart Failure - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "Peripheral edema" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "Peripheral edema" is most accurate?', '[{"id": "a", "text": "Cor pulmonale is a left-ventricular primary valvular disorder."}, {"id": "b", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "c", "text": "Peripheral edema is absent in right HF according to this note."}, {"id": "d", "text": "Right HF commonly causes bilateral peripheral pitting edema."}]'::jsonb, '["d"]'::jsonb, 'Correct because Right HF commonly causes bilateral peripheral pitting edema. Trend bilateral edema and rapid fluid changes.', 'Right-Left Heart Failure - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Weight rule physiology" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "Weight rule physiology" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Weight changes are considered unreliable and not used in HF monitoring."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "d", "text": "The note equates 1 kg to roughly 1 liter of retained fluid."}]'::jsonb, '["d"]'::jsonb, 'Correct because Rapid gain indicates fluid retention; 1 kg equals about 1 liter. Use objective weight data for early decompensation detection.', 'Right-Left Heart Failure - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Ascites/hepatomegaly" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "Ascites/hepatomegaly" in Right & Left Heart Failure?', '[{"id": "a", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "b", "text": "Recognize abdominal signs as venous-congestion progression."}, {"id": "c", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "d", "text": "Ascites is listed as a defining left-sided pulmonary finding."}]'::jsonb, '["b"]'::jsonb, 'Correct because Severe right HF can cause ascites and hepatomegaly with RUQ discomfort; GI congestion can cause nausea/anorexia. Recognize abdominal signs as venous-congestion progression.', 'Right-Left Heart Failure - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Cor pulmonale" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "Cor pulmonale" in Right & Left Heart Failure?', '[{"id": "a", "text": "Cor pulmonale is a left-ventricular primary valvular disorder."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "Identify cardiopulmonary linkage in chronic lung patients."}]'::jsonb, '["d"]'::jsonb, 'Correct because Chronic lung disease raises pulmonary vascular resistance and can lead to RV failure/right HF. Identify cardiopulmonary linkage in chronic lung patients.', 'Right-Left Heart Failure - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Comparison matrix" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Comparison matrix" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "Both sides are associated with the same valve pattern."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "Right HF primarily accumulates fluid in systemic tissues."}]'::jsonb, '["d"]'::jsonb, 'Correct because Left HF = lungs; right HF = body; BNP can be elevated in both; valve associations differ. Use pattern recognition for side differentiation.', 'Right-Left Heart Failure - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "General therapy" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "General therapy" is most accurate?', '[{"id": "a", "text": "Prioritize evidence-aligned daily management bundle."}, {"id": "b", "text": "Sodium loading is recommended."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "HFpEF is a dilated weak ventricle by definition."}]'::jsonb, '["a"]'::jsonb, 'Correct because General treatment includes diuretics, ACEI/ARB, beta-blockers, sodium restriction, daily weight monitoring, and fluid restriction in severe HF. Prioritize evidence-aligned daily management bundle.', 'Right-Left Heart Failure - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Weight reporting thresholds" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "Weight reporting thresholds" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Any weight change under 10 lb/day is ignored."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "Patients should report weight gain over 2 lb in 24 hours."}, {"id": "d", "text": "No further assessment is needed when symptoms fluctuate."}]'::jsonb, '["c"]'::jsonb, 'Correct because Report >2 lb in 24 h or >5 lb in a week. Escalate early before severe decompensation.', 'Right-Left Heart Failure - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Left-specific therapy" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "Left-specific therapy" in Right & Left Heart Failure?', '[{"id": "a", "text": "Immediate fluid bolus is first-line for pulmonary edema."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "Match intervention to pulmonary decompensation severity."}]'::jsonb, '["d"]'::jsonb, 'Correct because Left HF specifics include high Fowler positioning, O2/BiPAP for refractory pulmonary edema, digoxin for AF+HF rate control, spironolactone, LVAD/transplant for refractory HFrEF. Match intervention to pulmonary decompensation severity.', 'Right-Left Heart Failure - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Digoxin-furosemide risk" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "Digoxin-furosemide risk" in Right & Left Heart Failure?', '[{"id": "a", "text": "Furosemide can lower potassium, increasing digoxin toxicity risk."}, {"id": "b", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "c", "text": "Heart failure requires an ejection fraction below 20% in all patients."}, {"id": "d", "text": "Furosemide reliably raises potassium and protects from digoxin toxicity."}]'::jsonb, '["a"]'::jsonb, 'Correct because Furosemide can lower potassium, increasing digoxin toxicity risk. Prevent medication-related deterioration.', 'Right-Left Heart Failure - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Digoxin toxicity signs" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Digoxin toxicity signs" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "Visual halos are listed as benign and expected."}, {"id": "b", "text": "Nausea and vomiting are early digoxin toxicity signs."}, {"id": "c", "text": "Left HF pathophysiology excludes alveolar fluid leakage."}, {"id": "d", "text": "No further assessment is needed when symptoms fluctuate."}]'::jsonb, '["b"]'::jsonb, 'Correct because Early digoxin toxicity signs listed are nausea/vomiting and visual disturbances (halos). Hold and escalate promptly when early toxicity appears.', 'Right-Left Heart Failure - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "Digoxin hold thresholds" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "Digoxin hold thresholds" is most accurate?', '[{"id": "a", "text": "Hold digoxin for HR <60 adult, <70 child, <90 infant."}, {"id": "b", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "c", "text": "The same 60 bpm threshold applies to all ages."}, {"id": "d", "text": "This finding excludes heart failure when EF is preserved."}]'::jsonb, '["a"]'::jsonb, 'Correct because Hold digoxin for HR <60 adult, <70 child, <90 infant. Apply age-specific hold parameters accurately.', 'Right-Left Heart Failure - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "HF Definition" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "HF Definition" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Heart failure can cause backward fluid congestion."}, {"id": "b", "text": "EF alone is always enough to diagnose or exclude HF."}, {"id": "c", "text": "Heart failure always presents without fluid overload."}, {"id": "d", "text": "Orthopnea is identified as a right-sided-only symptom."}]'::jsonb, '["a"]'::jsonb, 'Correct because Heart failure is the inability of the heart to pump sufficient blood to meet metabolic needs. Recognize that congestion and low forward output can coexist.', 'Right-Left Heart Failure - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "HFrEF" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "HFrEF" in Right & Left Heart Failure?', '[{"id": "a", "text": "HFrEF is defined by EF above 50%."}, {"id": "b", "text": "Left-sided HF typically has no respiratory symptoms."}, {"id": "c", "text": "HFrEF has EF <40% with a dilated, weak heart."}, {"id": "d", "text": "Pulmonary edema is excluded from left HF."}]'::jsonb, '["c"]'::jsonb, 'Correct because HFrEF has EF <40% with a dilated, weak heart. Link reduced EF with weakened pump function.', 'Right-Left Heart Failure - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "HFpEF" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "HFpEF" in Right & Left Heart Failure?', '[{"id": "a", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "b", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "c", "text": "Avoid ruling out HF just because EF is preserved."}, {"id": "d", "text": "HFpEF is a dilated weak ventricle by definition."}]'::jsonb, '["c"]'::jsonb, 'Correct because HFpEF has EF >50% with a stiff, non-compliant heart. Avoid ruling out HF just because EF is preserved.', 'Right-Left Heart Failure - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "EF Range" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "EF Range" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "EF alone is always enough to diagnose or exclude HF."}, {"id": "b", "text": "Prioritize clinical symptoms over EF alone."}, {"id": "c", "text": "Right-sided HF has no venous pressure effects."}, {"id": "d", "text": "Any EF above 50% rules out heart failure."}]'::jsonb, '["b"]'::jsonb, 'Correct because Normal EF is 55-70%; HF diagnosis can still be made if symptoms are present regardless of EF. Prioritize clinical symptoms over EF alone.', 'Right-Left Heart Failure - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "Left HF Core" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "Left HF Core" is most accurate?', '[{"id": "a", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "b", "text": "Left-sided HF typically has no respiratory symptoms."}, {"id": "c", "text": "Left-sided HF primarily causes pulmonary congestion."}, {"id": "d", "text": "Right-sided HF is unrelated to chronic lung disease."}]'::jsonb, '["c"]'::jsonb, 'Correct because Left-sided HF primarily causes pulmonary congestion. Map left side findings to lung congestion.', 'Right-Left Heart Failure - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Left HF Causes" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "Left HF Causes" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "Tricuspid disease is listed as the most common isolated cause of left HF."}, {"id": "d", "text": "Anterior MI and chronic hypertension are common contributors."}]'::jsonb, '["d"]'::jsonb, 'Correct because Left HF causes include mitral/aortic valve disease, MI, chronic hypertension, cardiomyopathy. Connect structural and ischemic causes to LV failure.', 'Right-Left Heart Failure - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Left HF Path" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "Left HF Path" in Right & Left Heart Failure?', '[{"id": "a", "text": "JVD is listed as a hallmark of isolated left alveolar pathology."}, {"id": "b", "text": "LV failure first causes isolated portal venous congestion."}, {"id": "c", "text": "Pink frothy sputum is listed as a benign right-sided finding."}, {"id": "d", "text": "Increased pulmonary venous pressure can push fluid into alveoli."}]'::jsonb, '["d"]'::jsonb, 'Correct because LV failure backs blood into pulmonary veins; pressure rises and fluid leaks into alveoli causing pulmonary edema. Identify sequence leading to respiratory compromise.', 'Right-Left Heart Failure - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "DOE" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "DOE" in Right & Left Heart Failure?', '[{"id": "a", "text": "DOE appears only in right-sided HF section."}, {"id": "b", "text": "Progressive exertional intolerance supports worsening congestion."}, {"id": "c", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "d", "text": "Peripheral edema is absent in right HF according to this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Dyspnea on exertion is the first symptom listed for left HF. Escalate evaluation when exertional dyspnea appears in risk patients.', 'Right-Left Heart Failure - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Orthopnea and PND" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Orthopnea and PND" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "Orthopnea means inability to lie flat without dyspnea."}, {"id": "b", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "Orthopnea is identified as a right-sided-only symptom."}]'::jsonb, '["a"]'::jsonb, 'Correct because Orthopnea and PND are classic left-sided HF symptoms. Use nocturnal and positional dyspnea to triage severity.', 'Right-Left Heart Failure - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "Pulmonary edema" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "Pulmonary edema" is most accurate?', '[{"id": "a", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "b", "text": "Pink frothy sputum is listed as a benign right-sided finding."}, {"id": "c", "text": "Right-sided HF is unrelated to chronic lung disease."}, {"id": "d", "text": "Pink frothy sputum indicates severe pulmonary edema."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pink frothy sputum is a severe pulmonary edema sign in left HF. Treat as high-acuity respiratory compromise.', 'Right-Left Heart Failure - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "S3" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "S3" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "S3 may be present with left-sided congestion."}, {"id": "b", "text": "Chronic lung disease reduces RV workload."}, {"id": "c", "text": "RV failure directly causes only alveolar edema."}, {"id": "d", "text": "S3 is only a normal physiologic finding."}]'::jsonb, '["a"]'::jsonb, 'Correct because S3 gallop is described as a hallmark of heart failure (especially in left HF section). Interpret S3 with full volume-overload context.', 'Right-Left Heart Failure - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Right HF Core" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "Right HF Core" in Right & Left Heart Failure?', '[{"id": "a", "text": "JVD is listed as a hallmark of isolated left alveolar pathology."}, {"id": "b", "text": "BNP elevation is impossible in right HF according to this note."}, {"id": "c", "text": "Right-sided HF is described as isolated alveolar edema only."}, {"id": "d", "text": "Distinguish body-fluid retention pattern from pulmonary pattern."}]'::jsonb, '["d"]'::jsonb, 'Correct because Right-sided HF primarily causes systemic (peripheral) congestion. Distinguish body-fluid retention pattern from pulmonary pattern.', 'Right-Left Heart Failure - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Right HF Causes" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "Right HF Causes" in Right & Left Heart Failure?', '[{"id": "a", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "b", "text": "Left-sided HF is the most common cause of right-sided HF."}, {"id": "c", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "d", "text": "Aortic stenosis is listed as the dominant right-sided cause."}]'::jsonb, '["b"]'::jsonb, 'Correct because Most common right HF cause is left-sided HF; others include tricuspid disease, pulmonary HTN, RV MI, chronic lung disease. Search upstream causes when right-sided findings appear.', 'Right-Left Heart Failure - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Right HF Path" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Right HF Path" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "RV failure directly causes only alveolar edema."}, {"id": "b", "text": "Peripheral congestion results from this mechanism."}, {"id": "c", "text": "Any weight change under 10 lb/day is ignored."}, {"id": "d", "text": "RV failure lowers venous pressure and prevents edema."}]'::jsonb, '["b"]'::jsonb, 'Correct because RV failure causes venous backup and systemic fluid accumulation. Connect venous pressure rise to peripheral signs.', 'Right-Left Heart Failure - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "JVD" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "JVD" is most accurate?', '[{"id": "a", "text": "Hepatomegaly is unrelated to venous congestion."}, {"id": "b", "text": "Immediate fluid bolus is first-line for pulmonary edema."}, {"id": "c", "text": "JVD indicates low venous pressure."}, {"id": "d", "text": "JVD suggests elevated systemic venous pressure."}]'::jsonb, '["d"]'::jsonb, 'Correct because JVD reflects elevated venous pressure and is a major right HF sign. Use JVD as high-yield bedside congestion marker.', 'Right-Left Heart Failure - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Peripheral edema" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "Peripheral edema" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Cor pulmonale is a left-ventricular primary valvular disorder."}, {"id": "b", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "c", "text": "Right HF commonly causes bilateral peripheral pitting edema."}, {"id": "d", "text": "Peripheral edema is absent in right HF according to this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Right HF commonly causes bilateral peripheral pitting edema. Trend bilateral edema and rapid fluid changes.', 'Right-Left Heart Failure - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Weight rule physiology" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "Weight rule physiology" in Right & Left Heart Failure?', '[{"id": "a", "text": "Weight changes are considered unreliable and not used in HF monitoring."}, {"id": "b", "text": "BNP elevation is impossible in right HF according to this note."}, {"id": "c", "text": "Use objective weight data for early decompensation detection."}, {"id": "d", "text": "Fluid trends are not useful for cardiovascular reassessment."}]'::jsonb, '["c"]'::jsonb, 'Correct because Rapid gain indicates fluid retention; 1 kg equals about 1 liter. Use objective weight data for early decompensation detection.', 'Right-Left Heart Failure - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Ascites/hepatomegaly" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "Ascites/hepatomegaly" in Right & Left Heart Failure?', '[{"id": "a", "text": "Hepatomegaly with RUQ discomfort is linked to hepatic congestion."}, {"id": "b", "text": "Ascites is listed as a defining left-sided pulmonary finding."}, {"id": "c", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "d", "text": "Fluid trends are not useful for cardiovascular reassessment."}]'::jsonb, '["a"]'::jsonb, 'Correct because Severe right HF can cause ascites and hepatomegaly with RUQ discomfort; GI congestion can cause nausea/anorexia. Recognize abdominal signs as venous-congestion progression.', 'Right-Left Heart Failure - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Cor pulmonale" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Cor pulmonale" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "b", "text": "Cor pulmonale is a left-ventricular primary valvular disorder."}, {"id": "c", "text": "Cor pulmonale links chronic lung disease to right-sided HF."}, {"id": "d", "text": "Fluid trends are not useful for cardiovascular reassessment."}]'::jsonb, '["c"]'::jsonb, 'Correct because Chronic lung disease raises pulmonary vascular resistance and can lead to RV failure/right HF. Identify cardiopulmonary linkage in chronic lung patients.', 'Right-Left Heart Failure - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Right & Left Heart Failure note, which statement about "Comparison matrix" is most accurate?', 'According to the Right & Left Heart Failure note, which statement about "Comparison matrix" is most accurate?', '[{"id": "a", "text": "Use pattern recognition for side differentiation."}, {"id": "b", "text": "Both sides are associated with the same valve pattern."}, {"id": "c", "text": "Immediate fluid bolus is first-line for pulmonary edema."}, {"id": "d", "text": "No further assessment is needed when symptoms fluctuate."}]'::jsonb, '["a"]'::jsonb, 'Correct because Left HF = lungs; right HF = body; BNP can be elevated in both; valve associations differ. Use pattern recognition for side differentiation.', 'Right-Left Heart Failure - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "General therapy" in Right & Left Heart Failure. Which statement is correct?', 'The nurse is reviewing "General therapy" in Right & Left Heart Failure. Which statement is correct?', '[{"id": "a", "text": "Beta-blockers reduce workload in chronic HF care."}, {"id": "b", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "c", "text": "Sodium loading is recommended."}, {"id": "d", "text": "HFpEF is a dilated weak ventricle by definition."}]'::jsonb, '["a"]'::jsonb, 'Correct because General treatment includes diuretics, ACEI/ARB, beta-blockers, sodium restriction, daily weight monitoring, and fluid restriction in severe HF. Prioritize evidence-aligned daily management bundle.', 'Right-Left Heart Failure - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Weight reporting thresholds" in Right & Left Heart Failure?', 'Which clinical judgment is most accurate regarding "Weight reporting thresholds" in Right & Left Heart Failure?', '[{"id": "a", "text": "Any weight change under 10 lb/day is ignored."}, {"id": "b", "text": "Patients should report weight gain over 5 lb in one week."}, {"id": "c", "text": "This finding excludes heart failure when EF is preserved."}, {"id": "d", "text": "No further assessment is needed when symptoms fluctuate."}]'::jsonb, '["b"]'::jsonb, 'Correct because Report >2 lb in 24 h or >5 lb in a week. Escalate early before severe decompensation.', 'Right-Left Heart Failure - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Left-specific therapy" in Right & Left Heart Failure?', 'In rapid prioritization, which statement is most consistent with "Left-specific therapy" in Right & Left Heart Failure?', '[{"id": "a", "text": "Immediate fluid bolus is first-line for pulmonary edema."}, {"id": "b", "text": "High Fowler positioning helps reduce preload in left HF."}, {"id": "c", "text": "No further assessment is needed when symptoms fluctuate."}, {"id": "d", "text": "This finding excludes heart failure when EF is preserved."}]'::jsonb, '["b"]'::jsonb, 'Correct because Left HF specifics include high Fowler positioning, O2/BiPAP for refractory pulmonary edema, digoxin for AF+HF rate control, spironolactone, LVAD/transplant for refractory HFrEF. Match intervention to pulmonary decompensation severity.', 'Right-Left Heart Failure - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Digoxin-furosemide risk" in Right & Left Heart Failure would the nurse recognize as correct?', 'Which conclusion about "Digoxin-furosemide risk" in Right & Left Heart Failure would the nurse recognize as correct?', '[{"id": "a", "text": "Fluid trends are not useful for cardiovascular reassessment."}, {"id": "b", "text": "Furosemide reliably raises potassium and protects from digoxin toxicity."}, {"id": "c", "text": "Heart failure requires an ejection fraction below 20% in all patients."}, {"id": "d", "text": "Furosemide can lower potassium, increasing digoxin toxicity risk."}]'::jsonb, '["d"]'::jsonb, 'Correct because Furosemide can lower potassium, increasing digoxin toxicity risk. Prevent medication-related deterioration.', 'Right-Left Heart Failure - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "HF Definition" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "HF Definition" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "Heart failure means the heart cannot pump enough blood to meet metabolic demand."}, {"id": "b", "text": "Heart failure can reduce forward perfusion."}, {"id": "c", "text": "Heart failure always presents without fluid overload."}, {"id": "d", "text": "Heart failure requires an ejection fraction below 20% in all patients."}, {"id": "e", "text": "Heart failure can cause backward fluid congestion."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Heart failure is the inability of the heart to pump sufficient blood to meet metabolic needs.', 'Right-Left Heart Failure - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "HFrEF"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "HFrEF"? (Select all that apply)', '[{"id": "a", "text": "HFrEF is commonly described as a dilated, weak heart."}, {"id": "b", "text": "HFrEF is primarily a stiff non-compliant ventricle with preserved EF."}, {"id": "c", "text": "Reduced contractility contributes to poor forward output in HFrEF."}, {"id": "d", "text": "HFrEF is associated with EF below 40%."}, {"id": "e", "text": "HFrEF is defined by EF above 50%."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: HFrEF has EF <40% with a dilated, weak heart.', 'Right-Left Heart Failure - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "HFpEF" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "HFpEF" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "HFpEF is described as a stiff, non-compliant ventricle."}, {"id": "b", "text": "HFpEF is a dilated weak ventricle by definition."}, {"id": "c", "text": "HFpEF excludes all congestion symptoms."}, {"id": "d", "text": "HFpEF is associated with EF above 50%."}, {"id": "e", "text": "Symptoms may still indicate heart failure even with preserved EF."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: HFpEF has EF >50% with a stiff, non-compliant heart.', 'Right-Left Heart Failure - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "EF Range" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "EF Range" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Normal EF is approximately 55-70%."}, {"id": "b", "text": "Any EF above 50% rules out heart failure."}, {"id": "c", "text": "EF alone is always enough to diagnose or exclude HF."}, {"id": "d", "text": "A patient can have HF symptoms even when EF is preserved."}, {"id": "e", "text": "Symptoms remain central to HF diagnosis."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Normal EF is 55-70%; HF diagnosis can still be made if symptoms are present regardless of EF.', 'Right-Left Heart Failure - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Left HF Core" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Left HF Core" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Orthopnea strongly supports left-sided congestion."}, {"id": "b", "text": "Dyspnea and crackles are hallmark left-sided findings."}, {"id": "c", "text": "Left-sided HF causes pulmonary congestion."}, {"id": "d", "text": "Left-sided HF typically has no respiratory symptoms."}, {"id": "e", "text": "Left-sided HF primarily causes isolated ankle edema without lung findings."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Left-sided HF primarily causes pulmonary congestion.', 'Right-Left Heart Failure - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Left HF Causes" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "Left HF Causes" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "Anterior MI and chronic hypertension are common contributors."}, {"id": "b", "text": "Tricuspid disease is listed as the most common isolated cause of left HF."}, {"id": "c", "text": "Left HF is unrelated to cardiomyopathy."}, {"id": "d", "text": "Aortic valve disease can precipitate left-sided HF."}, {"id": "e", "text": "Mitral valve disease can cause left-sided HF."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Left HF causes include mitral/aortic valve disease, MI, chronic hypertension, cardiomyopathy.', 'Right-Left Heart Failure - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "Left HF Path"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "Left HF Path"? (Select all that apply)', '[{"id": "a", "text": "LV failure first causes isolated portal venous congestion."}, {"id": "b", "text": "Increased pulmonary venous pressure can push fluid into alveoli."}, {"id": "c", "text": "LV failure causes pulmonary venous backup."}, {"id": "d", "text": "Left HF pathophysiology excludes alveolar fluid leakage."}, {"id": "e", "text": "Pulmonary edema can result from this process."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: LV failure backs blood into pulmonary veins; pressure rises and fluid leaks into alveoli causing pulmonary edema.', 'Right-Left Heart Failure - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "DOE" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "DOE" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Progressive exertional intolerance supports worsening congestion."}, {"id": "b", "text": "DOE appears only in right-sided HF section."}, {"id": "c", "text": "DOE is unrelated to left HF."}, {"id": "d", "text": "DOE should prompt reassessment of fluid status and respiratory findings."}, {"id": "e", "text": "Dyspnea on exertion is an early left HF symptom."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Dyspnea on exertion is the first symptom listed for left HF.', 'Right-Left Heart Failure - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Orthopnea and PND" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "Orthopnea and PND" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "PND indicates isolated GI congestion."}, {"id": "b", "text": "Orthopnea means inability to lie flat without dyspnea."}, {"id": "c", "text": "Orthopnea is identified as a right-sided-only symptom."}, {"id": "d", "text": "Both findings support pulmonary congestion from left HF."}, {"id": "e", "text": "PND involves waking at night gasping for air."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Orthopnea and PND are classic left-sided HF symptoms.', 'Right-Left Heart Failure - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Pulmonary edema" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Pulmonary edema" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Pulmonary edema is excluded from left HF."}, {"id": "b", "text": "Pulmonary edema is strongly linked to left-sided failure."}, {"id": "c", "text": "Pink frothy sputum is listed as a benign right-sided finding."}, {"id": "d", "text": "Respiratory compromise may escalate rapidly when this appears."}, {"id": "e", "text": "Pink frothy sputum indicates severe pulmonary edema."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pink frothy sputum is a severe pulmonary edema sign in left HF.', 'Right-Left Heart Failure - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "S3" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "S3" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "S3 is only a normal physiologic finding."}, {"id": "b", "text": "S3 should be integrated with dyspnea, crackles, and edema findings."}, {"id": "c", "text": "S3 gallop is a hallmark heart failure clue."}, {"id": "d", "text": "S3 may be present with left-sided congestion."}, {"id": "e", "text": "S3 excludes heart failure."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: S3 gallop is described as a hallmark of heart failure (especially in left HF section).', 'Right-Left Heart Failure - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "Right HF Core"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "Right HF Core"? (Select all that apply)', '[{"id": "a", "text": "Right-sided HF causes systemic venous congestion."}, {"id": "b", "text": "Peripheral edema and JVD are key right-sided clues."}, {"id": "c", "text": "Right-sided HF is described as isolated alveolar edema only."}, {"id": "d", "text": "Weight gain from fluid retention supports right-sided congestion."}, {"id": "e", "text": "Right-sided HF has no venous pressure effects."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Right-sided HF primarily causes systemic (peripheral) congestion.', 'Right-Left Heart Failure - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Right HF Causes" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "Right HF Causes" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Left-sided HF is the most common cause of right-sided HF."}, {"id": "b", "text": "RV MI and tricuspid disease are listed right-sided causes."}, {"id": "c", "text": "Right-sided HF is unrelated to chronic lung disease."}, {"id": "d", "text": "Aortic stenosis is listed as the dominant right-sided cause."}, {"id": "e", "text": "Pulmonary hypertension can drive right-sided failure."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Most common right HF cause is left-sided HF; others include tricuspid disease, pulmonary HTN, RV MI, chronic lung disease.', 'Right-Left Heart Failure - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Right HF Path" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "Right HF Path" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Systemic venous pressure rise promotes body fluid accumulation."}, {"id": "b", "text": "RV failure causes blood to back up in venous circulation."}, {"id": "c", "text": "RV failure lowers venous pressure and prevents edema."}, {"id": "d", "text": "Peripheral congestion results from this mechanism."}, {"id": "e", "text": "RV failure directly causes only alveolar edema."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: RV failure causes venous backup and systemic fluid accumulation.', 'Right-Left Heart Failure - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "JVD" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "JVD" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "JVD is listed as a hallmark of isolated left alveolar pathology."}, {"id": "b", "text": "JVD indicates low venous pressure."}, {"id": "c", "text": "JVD is emphasized in right-sided HF symptom profile."}, {"id": "d", "text": "JVD suggests elevated systemic venous pressure."}, {"id": "e", "text": "JVD with edema supports peripheral congestion."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: JVD reflects elevated venous pressure and is a major right HF sign.', 'Right-Left Heart Failure - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Peripheral edema" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "Peripheral edema" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "Peripheral edema should be interpreted with weight trends and JVD."}, {"id": "b", "text": "Unilateral trauma edema is listed as classic HF edema."}, {"id": "c", "text": "Dependent leg/ankle swelling is expected in systemic fluid overload."}, {"id": "d", "text": "Peripheral edema is absent in right HF according to this note."}, {"id": "e", "text": "Bilateral pitting edema supports right-sided congestion."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Right HF commonly causes bilateral peripheral pitting edema.', 'Right-Left Heart Failure - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "Weight rule physiology"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "Weight rule physiology"? (Select all that apply)', '[{"id": "a", "text": "The note equates 1 kg to roughly 1 liter of retained fluid."}, {"id": "b", "text": "Weight changes are considered unreliable and not used in HF monitoring."}, {"id": "c", "text": "Rapid weight gain indicates fluid retention."}, {"id": "d", "text": "The note states 1 kg equals 100 mL of fluid."}, {"id": "e", "text": "Daily weights are a core monitoring strategy."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Rapid gain indicates fluid retention; 1 kg equals about 1 liter.', 'Right-Left Heart Failure - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Ascites/hepatomegaly" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "Ascites/hepatomegaly" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Hepatomegaly is unrelated to venous congestion."}, {"id": "b", "text": "GI congestion may cause nausea and anorexia."}, {"id": "c", "text": "Ascites is listed as a defining left-sided pulmonary finding."}, {"id": "d", "text": "Ascites can occur in severe right-sided HF."}, {"id": "e", "text": "Hepatomegaly with RUQ discomfort is linked to hepatic congestion."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Severe right HF can cause ascites and hepatomegaly with RUQ discomfort; GI congestion can cause nausea/anorexia.', 'Right-Left Heart Failure - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Cor pulmonale" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "Cor pulmonale" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Cor pulmonale is a left-ventricular primary valvular disorder."}, {"id": "b", "text": "Increased pulmonary vascular resistance increases RV workload."}, {"id": "c", "text": "JVD and peripheral edema can appear in COPD-related right HF."}, {"id": "d", "text": "Chronic lung disease reduces RV workload."}, {"id": "e", "text": "Cor pulmonale links chronic lung disease to right-sided HF."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Chronic lung disease raises pulmonary vascular resistance and can lead to RV failure/right HF.', 'Right-Left Heart Failure - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Comparison matrix" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Comparison matrix" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Left HF primarily accumulates fluid in lungs."}, {"id": "b", "text": "BNP elevation is impossible in right HF according to this note."}, {"id": "c", "text": "Right HF primarily accumulates fluid in systemic tissues."}, {"id": "d", "text": "Both sides are associated with the same valve pattern."}, {"id": "e", "text": "BNP can be elevated in both left and right HF."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Left HF = lungs; right HF = body; BNP can be elevated in both; valve associations differ.', 'Right-Left Heart Failure - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "General therapy" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "General therapy" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "Daily weights are discouraged."}, {"id": "b", "text": "Diuretics are used to reduce fluid overload."}, {"id": "c", "text": "ACE inhibitors or ARBs help reduce afterload and improve survival."}, {"id": "d", "text": "Beta-blockers reduce workload in chronic HF care."}, {"id": "e", "text": "Sodium loading is recommended."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: General treatment includes diuretics, ACEI/ARB, beta-blockers, sodium restriction, daily weight monitoring, and fluid restriction in severe HF.', 'Right-Left Heart Failure - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "Weight reporting thresholds"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "Weight reporting thresholds"? (Select all that apply)', '[{"id": "a", "text": "Patients should report weight gain over 5 lb in one week."}, {"id": "b", "text": "Daily weighing time variability is preferred."}, {"id": "c", "text": "Using same time and same scale is emphasized."}, {"id": "d", "text": "Patients should report weight gain over 2 lb in 24 hours."}, {"id": "e", "text": "Any weight change under 10 lb/day is ignored."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Report >2 lb in 24 h or >5 lb in a week.', 'Right-Left Heart Failure - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Left-specific therapy" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "Left-specific therapy" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "BiPAP is used for refractory pulmonary edema."}, {"id": "b", "text": "High Fowler positioning helps reduce preload in left HF."}, {"id": "c", "text": "Immediate fluid bolus is first-line for pulmonary edema."}, {"id": "d", "text": "BiPAP is contraindicated in refractory pulmonary edema per this note."}, {"id": "e", "text": "LVAD or transplant is considered in refractory HFrEF."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Left HF specifics include high Fowler positioning, O2/BiPAP for refractory pulmonary edema, digoxin for AF+HF rate control, spironolactone, LVAD/transplant for refractory HFrEF.', 'Right-Left Heart Failure - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Digoxin-furosemide risk" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "Digoxin-furosemide risk" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Loop diuretic-related hypokalemia increases digoxin toxicity risk."}, {"id": "b", "text": "Potassium monitoring is important when furosemide and digoxin are combined."}, {"id": "c", "text": "Medication safety requires rhythm and symptom surveillance."}, {"id": "d", "text": "Furosemide reliably raises potassium and protects from digoxin toxicity."}, {"id": "e", "text": "No electrolyte monitoring is needed when combining these drugs per this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Furosemide can lower potassium, increasing digoxin toxicity risk.', 'Right-Left Heart Failure - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Digoxin toxicity signs" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Digoxin toxicity signs" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Nausea and vomiting are early digoxin toxicity signs."}, {"id": "b", "text": "Visual halos are listed as benign and expected."}, {"id": "c", "text": "Visual halos are a toxicity warning sign."}, {"id": "d", "text": "These findings warrant prompt medication review and provider notification."}, {"id": "e", "text": "Digoxin toxicity is described as asymptomatic."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Early digoxin toxicity signs listed are nausea/vomiting and visual disturbances (halos).', 'Right-Left Heart Failure - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Digoxin hold thresholds" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "Digoxin hold thresholds" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "Digoxin is never held for bradycardia."}, {"id": "b", "text": "Hold digoxin when adult HR is below 60."}, {"id": "c", "text": "Hold digoxin when child HR is below 70."}, {"id": "d", "text": "Hold digoxin when infant HR is below 90."}, {"id": "e", "text": "The same 60 bpm threshold applies to all ages."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Hold digoxin for HR <60 adult, <70 child, <90 infant.', 'Right-Left Heart Failure - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "HF Definition"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "HF Definition"? (Select all that apply)', '[{"id": "a", "text": "Heart failure can reduce forward perfusion."}, {"id": "b", "text": "Heart failure always presents without fluid overload."}, {"id": "c", "text": "Heart failure means the heart cannot pump enough blood to meet metabolic demand."}, {"id": "d", "text": "Heart failure requires an ejection fraction below 20% in all patients."}, {"id": "e", "text": "Heart failure can cause backward fluid congestion."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Heart failure is the inability of the heart to pump sufficient blood to meet metabolic needs.', 'Right-Left Heart Failure - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "HFrEF" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "HFrEF" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "HFrEF is primarily a stiff non-compliant ventricle with preserved EF."}, {"id": "b", "text": "Reduced contractility contributes to poor forward output in HFrEF."}, {"id": "c", "text": "HFrEF is defined by EF above 50%."}, {"id": "d", "text": "HFrEF is associated with EF below 40%."}, {"id": "e", "text": "HFrEF is commonly described as a dilated, weak heart."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: HFrEF has EF <40% with a dilated, weak heart.', 'Right-Left Heart Failure - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "HFpEF" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "HFpEF" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Symptoms may still indicate heart failure even with preserved EF."}, {"id": "b", "text": "HFpEF is associated with EF above 50%."}, {"id": "c", "text": "HFpEF is a dilated weak ventricle by definition."}, {"id": "d", "text": "HFpEF excludes all congestion symptoms."}, {"id": "e", "text": "HFpEF is described as a stiff, non-compliant ventricle."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: HFpEF has EF >50% with a stiff, non-compliant heart.', 'Right-Left Heart Failure - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "EF Range" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "EF Range" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "A patient can have HF symptoms even when EF is preserved."}, {"id": "b", "text": "Symptoms remain central to HF diagnosis."}, {"id": "c", "text": "Any EF above 50% rules out heart failure."}, {"id": "d", "text": "EF alone is always enough to diagnose or exclude HF."}, {"id": "e", "text": "Normal EF is approximately 55-70%."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Normal EF is 55-70%; HF diagnosis can still be made if symptoms are present regardless of EF.', 'Right-Left Heart Failure - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Left HF Core" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "Left HF Core" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "Orthopnea strongly supports left-sided congestion."}, {"id": "b", "text": "Dyspnea and crackles are hallmark left-sided findings."}, {"id": "c", "text": "Left-sided HF typically has no respiratory symptoms."}, {"id": "d", "text": "Left-sided HF causes pulmonary congestion."}, {"id": "e", "text": "Left-sided HF primarily causes isolated ankle edema without lung findings."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Left-sided HF primarily causes pulmonary congestion.', 'Right-Left Heart Failure - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "Left HF Causes"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "Left HF Causes"? (Select all that apply)', '[{"id": "a", "text": "Anterior MI and chronic hypertension are common contributors."}, {"id": "b", "text": "Left HF is unrelated to cardiomyopathy."}, {"id": "c", "text": "Aortic valve disease can precipitate left-sided HF."}, {"id": "d", "text": "Tricuspid disease is listed as the most common isolated cause of left HF."}, {"id": "e", "text": "Mitral valve disease can cause left-sided HF."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Left HF causes include mitral/aortic valve disease, MI, chronic hypertension, cardiomyopathy.', 'Right-Left Heart Failure - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Left HF Path" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "Left HF Path" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "LV failure causes pulmonary venous backup."}, {"id": "b", "text": "Left HF pathophysiology excludes alveolar fluid leakage."}, {"id": "c", "text": "Pulmonary edema can result from this process."}, {"id": "d", "text": "Increased pulmonary venous pressure can push fluid into alveoli."}, {"id": "e", "text": "LV failure first causes isolated portal venous congestion."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: LV failure backs blood into pulmonary veins; pressure rises and fluid leaks into alveoli causing pulmonary edema.', 'Right-Left Heart Failure - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "DOE" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "DOE" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "DOE should prompt reassessment of fluid status and respiratory findings."}, {"id": "b", "text": "DOE appears only in right-sided HF section."}, {"id": "c", "text": "DOE is unrelated to left HF."}, {"id": "d", "text": "Progressive exertional intolerance supports worsening congestion."}, {"id": "e", "text": "Dyspnea on exertion is an early left HF symptom."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Dyspnea on exertion is the first symptom listed for left HF.', 'Right-Left Heart Failure - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Orthopnea and PND" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Orthopnea and PND" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Both findings support pulmonary congestion from left HF."}, {"id": "b", "text": "Orthopnea is identified as a right-sided-only symptom."}, {"id": "c", "text": "PND involves waking at night gasping for air."}, {"id": "d", "text": "PND indicates isolated GI congestion."}, {"id": "e", "text": "Orthopnea means inability to lie flat without dyspnea."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Orthopnea and PND are classic left-sided HF symptoms.', 'Right-Left Heart Failure - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Pulmonary edema" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "Pulmonary edema" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "Pulmonary edema is excluded from left HF."}, {"id": "b", "text": "Pink frothy sputum is listed as a benign right-sided finding."}, {"id": "c", "text": "Respiratory compromise may escalate rapidly when this appears."}, {"id": "d", "text": "Pulmonary edema is strongly linked to left-sided failure."}, {"id": "e", "text": "Pink frothy sputum indicates severe pulmonary edema."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pink frothy sputum is a severe pulmonary edema sign in left HF.', 'Right-Left Heart Failure - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "S3"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "S3"? (Select all that apply)', '[{"id": "a", "text": "S3 gallop is a hallmark heart failure clue."}, {"id": "b", "text": "S3 should be integrated with dyspnea, crackles, and edema findings."}, {"id": "c", "text": "S3 is only a normal physiologic finding."}, {"id": "d", "text": "S3 may be present with left-sided congestion."}, {"id": "e", "text": "S3 excludes heart failure."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: S3 gallop is described as a hallmark of heart failure (especially in left HF section).', 'Right-Left Heart Failure - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Right HF Core" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "Right HF Core" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Right-sided HF is described as isolated alveolar edema only."}, {"id": "b", "text": "Right-sided HF has no venous pressure effects."}, {"id": "c", "text": "Peripheral edema and JVD are key right-sided clues."}, {"id": "d", "text": "Weight gain from fluid retention supports right-sided congestion."}, {"id": "e", "text": "Right-sided HF causes systemic venous congestion."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Right-sided HF primarily causes systemic (peripheral) congestion.', 'Right-Left Heart Failure - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Right HF Causes" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "Right HF Causes" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Right-sided HF is unrelated to chronic lung disease."}, {"id": "b", "text": "Aortic stenosis is listed as the dominant right-sided cause."}, {"id": "c", "text": "RV MI and tricuspid disease are listed right-sided causes."}, {"id": "d", "text": "Pulmonary hypertension can drive right-sided failure."}, {"id": "e", "text": "Left-sided HF is the most common cause of right-sided HF."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Most common right HF cause is left-sided HF; others include tricuspid disease, pulmonary HTN, RV MI, chronic lung disease.', 'Right-Left Heart Failure - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Right HF Path" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Right HF Path" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Systemic venous pressure rise promotes body fluid accumulation."}, {"id": "b", "text": "RV failure causes blood to back up in venous circulation."}, {"id": "c", "text": "RV failure lowers venous pressure and prevents edema."}, {"id": "d", "text": "RV failure directly causes only alveolar edema."}, {"id": "e", "text": "Peripheral congestion results from this mechanism."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: RV failure causes venous backup and systemic fluid accumulation.', 'Right-Left Heart Failure - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "JVD" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "JVD" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "JVD indicates low venous pressure."}, {"id": "b", "text": "JVD is listed as a hallmark of isolated left alveolar pathology."}, {"id": "c", "text": "JVD with edema supports peripheral congestion."}, {"id": "d", "text": "JVD suggests elevated systemic venous pressure."}, {"id": "e", "text": "JVD is emphasized in right-sided HF symptom profile."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: JVD reflects elevated venous pressure and is a major right HF sign.', 'Right-Left Heart Failure - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "Peripheral edema"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "Peripheral edema"? (Select all that apply)', '[{"id": "a", "text": "Dependent leg/ankle swelling is expected in systemic fluid overload."}, {"id": "b", "text": "Peripheral edema should be interpreted with weight trends and JVD."}, {"id": "c", "text": "Bilateral pitting edema supports right-sided congestion."}, {"id": "d", "text": "Unilateral trauma edema is listed as classic HF edema."}, {"id": "e", "text": "Peripheral edema is absent in right HF according to this note."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Right HF commonly causes bilateral peripheral pitting edema.', 'Right-Left Heart Failure - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Weight rule physiology" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "Weight rule physiology" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "The note equates 1 kg to roughly 1 liter of retained fluid."}, {"id": "b", "text": "Daily weights are a core monitoring strategy."}, {"id": "c", "text": "The note states 1 kg equals 100 mL of fluid."}, {"id": "d", "text": "Weight changes are considered unreliable and not used in HF monitoring."}, {"id": "e", "text": "Rapid weight gain indicates fluid retention."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Rapid gain indicates fluid retention; 1 kg equals about 1 liter.', 'Right-Left Heart Failure - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Ascites/hepatomegaly" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "Ascites/hepatomegaly" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "GI congestion may cause nausea and anorexia."}, {"id": "b", "text": "Ascites can occur in severe right-sided HF."}, {"id": "c", "text": "Hepatomegaly is unrelated to venous congestion."}, {"id": "d", "text": "Hepatomegaly with RUQ discomfort is linked to hepatic congestion."}, {"id": "e", "text": "Ascites is listed as a defining left-sided pulmonary finding."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Severe right HF can cause ascites and hepatomegaly with RUQ discomfort; GI congestion can cause nausea/anorexia.', 'Right-Left Heart Failure - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Cor pulmonale" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Cor pulmonale" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Chronic lung disease reduces RV workload."}, {"id": "b", "text": "JVD and peripheral edema can appear in COPD-related right HF."}, {"id": "c", "text": "Cor pulmonale is a left-ventricular primary valvular disorder."}, {"id": "d", "text": "Cor pulmonale links chronic lung disease to right-sided HF."}, {"id": "e", "text": "Increased pulmonary vascular resistance increases RV workload."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Chronic lung disease raises pulmonary vascular resistance and can lead to RV failure/right HF.', 'Right-Left Heart Failure - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Comparison matrix" in Right & Left Heart Failure are correct? (Select all that apply)', 'Which statements about "Comparison matrix" in Right & Left Heart Failure are correct? (Select all that apply)', '[{"id": "a", "text": "BNP can be elevated in both left and right HF."}, {"id": "b", "text": "Both sides are associated with the same valve pattern."}, {"id": "c", "text": "BNP elevation is impossible in right HF according to this note."}, {"id": "d", "text": "Right HF primarily accumulates fluid in systemic tissues."}, {"id": "e", "text": "Left HF primarily accumulates fluid in lungs."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Left HF = lungs; right HF = body; BNP can be elevated in both; valve associations differ.', 'Right-Left Heart Failure - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Right & Left Heart Failure, which findings or actions relate to "General therapy"? (Select all that apply)', 'For Right & Left Heart Failure, which findings or actions relate to "General therapy"? (Select all that apply)', '[{"id": "a", "text": "Sodium loading is recommended."}, {"id": "b", "text": "Daily weights are discouraged."}, {"id": "c", "text": "Beta-blockers reduce workload in chronic HF care."}, {"id": "d", "text": "ACE inhibitors or ARBs help reduce afterload and improve survival."}, {"id": "e", "text": "Diuretics are used to reduce fluid overload."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: General treatment includes diuretics, ACEI/ARB, beta-blockers, sodium restriction, daily weight monitoring, and fluid restriction in severe HF.', 'Right-Left Heart Failure - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Weight reporting thresholds" in Right & Left Heart Failure? (Select all that apply)', 'The nurse is planning care. Which items apply to "Weight reporting thresholds" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Any weight change under 10 lb/day is ignored."}, {"id": "b", "text": "Patients should report weight gain over 5 lb in one week."}, {"id": "c", "text": "Using same time and same scale is emphasized."}, {"id": "d", "text": "Patients should report weight gain over 2 lb in 24 hours."}, {"id": "e", "text": "Daily weighing time variability is preferred."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Report >2 lb in 24 h or >5 lb in a week.', 'Right-Left Heart Failure - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Left-specific therapy" in Right & Left Heart Failure? (Select all that apply)', 'Which of the following are consistent with "Left-specific therapy" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "BiPAP is contraindicated in refractory pulmonary edema per this note."}, {"id": "b", "text": "High Fowler positioning helps reduce preload in left HF."}, {"id": "c", "text": "LVAD or transplant is considered in refractory HFrEF."}, {"id": "d", "text": "Immediate fluid bolus is first-line for pulmonary edema."}, {"id": "e", "text": "BiPAP is used for refractory pulmonary edema."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Left HF specifics include high Fowler positioning, O2/BiPAP for refractory pulmonary edema, digoxin for AF+HF rate control, spironolactone, LVAD/transplant for refractory HFrEF.', 'Right-Left Heart Failure - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Digoxin-furosemide risk" in Right & Left Heart Failure? (Select all that apply)', 'During reassessment, which observations align with "Digoxin-furosemide risk" in Right & Left Heart Failure? (Select all that apply)', '[{"id": "a", "text": "Loop diuretic-related hypokalemia increases digoxin toxicity risk."}, {"id": "b", "text": "Furosemide reliably raises potassium and protects from digoxin toxicity."}, {"id": "c", "text": "Potassium monitoring is important when furosemide and digoxin are combined."}, {"id": "d", "text": "No electrolyte monitoring is needed when combining these drugs per this note."}, {"id": "e", "text": "Medication safety requires rhythm and symptom surveillance."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Furosemide can lower potassium, increasing digoxin toxicity risk.', 'Right-Left Heart Failure - NCLEX', true, 100, 1, true);
